import pandas as pd
import numpy as np
import random

# Load the data
df = pd.read_csv('chunks_csv/changespillover/changespillover_2021_2023_no2.csv')
adjacency_df = pd.read_csv('chunks_csv/borough_adjacency.csv')

# Calculate the change in NO2 between 2021 and 2023
df['change'] = df['NO2_2023'] - df['NO2_2021']

# Create a dictionary to map boroughs to their neighbors
neighbor_dict = {}
for index, row in adjacency_df.iterrows():
    if row['borough'] not in neighbor_dict:
        neighbor_dict[row['borough']] = []
    neighbor_dict[row['borough']].append(row['neighbor'])

# Create a list of all boroughs
all_boroughs = list(set(df['borough'].tolist() + [neighbor for neighbors in neighbor_dict.values() for neighbor in neighbors]))

# Create a dictionary to map each borough to its neighbors' changes
neighbor_changes = {}
for borough in all_boroughs:
    if borough in neighbor_dict:
        neighbor_changes[borough] = []
        for neighbor in neighbor_dict[borough]:
            if neighbor in df['borough'].tolist():
                neighbor_changes[borough].append(df.loc[df['borough'] == neighbor, 'change'].values[0])

# Calculate the average change for each borough
avg_change = {}
for borough in all_boroughs:
    if borough in neighbor_dict:
        avg_change[borough] = np.mean(neighbor_changes[borough])

# Calculate the correlation between each borough's change and its neighbors' changes
correlation = {}
for borough in all_boroughs:
    if borough in neighbor_dict:
        changes = [neighbor_change for neighbor_change in neighbor_changes[borough] if not np.isnan(neighbor_change)]
        correlation[borough] = np.corrcoef([avg_change[borough], np.mean(changes)])[0, 1]

# Perform a permutation test to determine the significance of the correlation
p_value = 0
