            shuffled_changes[borough] = [neighbor_change for neighbor_change in shuffled_changes[borough] if not np.isnan(neighbor_change)]
            shuffled_correlation[borough] = np.corrcoef([avg_change[borough], np.mean(shuffled_changes[borough])])[0, 1]
    # Calculate the correlation between each borough's change and its neighbors' changes in the original data
    original_correlation = {}
    for borough in all_boroughs:
        if borough in neighbor_dict:
            original_correlation[borough] = np.corrcoef([avg_change[borough], np.mean(neighbor_changes[borough])])[0, 1]
    # Check if the original correlation is more extreme than the shuffled correlations
    if np.abs(np.mean([correlation[borough] for borough in all_boroughs if borough in neighbor_dict])) > np.abs(np.mean([shuffled_correlation[borough] for borough in all_boroughs if borough in neighbor_dict])):
        p_value += 1
p_value /= 500

print(f"p = {p_value}")

# Print the final answer
